def f(g):
    from collections import Counter
    c=Counter(x for r in g for x in r)
    bg=c.most_common(1)[0][0]
    out=[]
    for r in g:
        if any(x!=bg for x in r):
            out.append([1 if x==bg else x for x in r])
        else:
            out.append(r)
    return out
